"""Verify the RDH loader with relocations generated by the matched objects."""
import argparse
from collections import Counter
import json
from pathlib import Path

import link_enginera
import link_libraries
import verify_control
from rdh import Fixup, Image, OBJECTS, ROOT, build_loader


def ordered_pages(order, known, reference):
    """Apply the saved linker order and put cross-page operands in both pages."""
    page_bases = [obj.base + 4096 * j for obj in OBJECTS for j in range(obj.pages)]
    if len(order) != len(page_bases):
        raise ValueError("Unexpected relocation page count")
    seen = Counter()
    generated_records = 0
    pages = []
    for base, offsets in zip(page_bases, order, strict=True):
        page = []
        for offset in offsets:
            if not -3 <= offset < 4096:
                raise ValueError(f"Invalid relocation offset at page {base:#x}")
            if offset < 0 and base - 4096 not in page_bases:
                raise ValueError(f"Cross-page relocation has no preceding page at {base:#x}")
            address = base + offset
            if address in known:
                fixup = Fixup(*known[address])
                generated_records += 1
            else:
                fixup = reference[address]
            seen[address] += 1
            page.append((address, fixup))
        pages.append(page)
    expected = Counter()
    for obj in OBJECTS:
        for address in reference.keys() | known.keys():
            if obj.base <= address < obj.base + 4096 * obj.pages:
                offset = address - obj.base
                expected[address] = 1 + (offset % 4096 > 4092 and offset // 4096 + 1 < obj.pages)
    if seen != expected or not known.keys() <= seen.keys():
        raise ValueError("Missing, duplicate, or misplaced relocation sites")
    return pages, generated_records


def generate_sections(image, upstream, watcom_lib386, nasm, work, *, collect=None,
                      c_compiler=verify_control.DEFAULT_C_COMPILER,
                      c_runner=verify_control.DEFAULT_C_RUNNER,
                      dosbox=verify_control.DEFAULT_DOSBOX):
    data = ROOT / "tools/data"
    known = {}
    bindings = json.loads((data / "enginera-bindings.json").read_text(encoding="utf-8"))
    link_enginera.verify(image, upstream / "enginera", bindings, work / "enginera", known, collect=collect)
    manifest = json.loads((data / "library-layout.json").read_text(encoding="utf-8"))
    libraries = {
        "watcom": watcom_lib386 / "DOS/CLIB3R.LIB",
        "math": watcom_lib386 / "MATH387R.LIB",
        "emu": watcom_lib386 / "DOS/EMU387.LIB",
        "audio": upstream / "AUDIO_WF.LIB",
        "mact": upstream / "mact/MACT386.LIB",
    }
    link_libraries.verify(image, libraries, manifest, work / "libraries", known, collect=collect)
    if nasm:
        verify_control.verify(image, nasm, work / "control", known, collect=collect,
                              c_compiler=c_compiler, c_runner=c_runner, dosbox=dosbox)
    return known


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("original", type=Path)
    parser.add_argument("setmain", type=Path)
    parser.add_argument("upstream", type=Path)
    parser.add_argument("watcom_lib386", type=Path)
    parser.add_argument("--nasm", type=Path, help="include standalone RDH code and action table fixups")
    parser.add_argument("--c-compiler", type=Path, default=verify_control.DEFAULT_C_COMPILER)
    parser.add_argument("--c-runner", type=Path, default=verify_control.DEFAULT_C_RUNNER)
    parser.add_argument("--dosbox", type=Path, default=verify_control.DEFAULT_DOSBOX)
    args = parser.parse_args()
    image = Image(args.original.read_bytes())
    data = ROOT / "tools/data"
    known = generate_sections(image, args.upstream, args.watcom_lib386, args.nasm, ROOT / "work",
                              c_compiler=args.c_compiler, c_runner=args.c_runner,
                              dosbox=args.dosbox)
    order = json.loads((data / "relocation-order.json").read_text(encoding="utf-8"))
    pages, generated = ordered_pages(order, known, image.fixups)
    prefix = build_loader(args.setmain.read_bytes(), pages)
    if prefix != image.blob[:image.data_offset]:
        raise ValueError("Generated loader prefix differs")
    print(json.dumps({
        "matching_prefix_bytes": len(prefix),
        "object_generated_sites": len(known),
        "object_generated_records": generated,
        "object_generated_record_bytes": sum(
            9 if fixup.flags & 16 else 7
            for page in pages for address, fixup in page if address in known
        ),
        "reference_sites": len(image.fixups) - len(known),
        "reference_records": len(image.records) - generated,
    }, indent=2))


if __name__ == "__main__":
    main()
